Ext._define('planning.hiring.meterage.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'planning.hiring.meterage.Window',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'pay', 'unpay', 'dispatch', '-', 'report',  '-', 'search'],

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Status', dataIndex: 'icons', sortable: true, renderer: core.rendererIconGrid, menuDisabled: true},
                    {header: 'Responsável', dataIndex: 'user_display', sortable: true, id: 'autoExpandColumn'},
                    {header: 'Valor', dataIndex: 'valor', sortable: true, renderer: toolkit.util.formatCurrency},
                    {header: 'OB', dataIndex: 'ordem_bancaria', sortable: true, width: 90},
                    {header: 'NE', dataIndex: 'nota_empenho_display', sortable: true, width: 90},
                    {header: 'Período de Referência', dataIndex: 'periodo_display', sortable: true, width: 155},
                ]
            );

        return this._columnModel;
    },

    dispatchPayment: function() {
        var sels = this.getSelectionModel().getSelections().map(item => item.id);

        if(sels.length > 0) {
            var rest = Ext._create('planning.hiring.meterage.Restful');

            var mask = new Ext.LoadMask(this.getEl(), {
                msg: 'Gerando solicitação de pagamento...'
            });

            rest.dispatch(
                sels,
                {
                    scope: this,
                    fn: function(message) {
                        var _window = Ext._create(
                            'planning.hiring.meterage.DispatchTextWindow'
                        );
                        _window.setMessage(message.message);
                        _window.show();
                    }
                },
                {
                    fn: function(message) {
                        Ext.Msg.show({
                            title: 'Falha na comunicação',
                            msg: message,
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK
                        });
                    }
                },
                {
                    fn: function() {
                        mask.hide();
                        delete mask;
                    }
                }
            );
        }
        else {
            Ext.Msg.show({
                title: 'Informação',
                icon: Ext.Msg.INFO,
                buttons: Ext.Msg.OK,
                msg: 'Selecione pelo menos um pagamento.'
            });
        }
    },

    getDispatchAction: function() {
        if(!this._dispatchAction)
            this._dispatchAction = Ext._create('Ext.Button', {
                text: 'Despacho',
                iconCls: 'icon-core icon-core-reports',
                scope: this,
                handler: this.dispatchPayment
            });

        return this._dispatchAction;
    },

    getPayAction: function() {
        if(!this._payAction)
            this._payAction = Ext._create('Ext.Button', {
                text: 'Lançar Pagamento',
                iconCls: 'icon-agree icon-agree-payment-finish',
                scope: this,
                handler: this._payTheMan
            });

        return this._payAction;
    },

    getUnpayAction: function() {
        if(!this._unpayAction)
            this._unpayAction = Ext._create('Ext.Button', {
                text: 'Desfazer Pagamento',
                iconCls: 'icon-agree icon-agree-delete',
                scope: this,
                handler: this._unpayTheMan
            });

        return this._unpayAction;
    },

    _unpayTheMan: function() {
        var sels = this.getSelectionModel().getSelections();

        if(sels.length > 0) {
            var mask = new Ext.LoadMask(this.getEl(), {msg: 'Desfazendo Pagamento...'});

            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                msg: 'Tem certeza que deseja desfazer o pagamento selecionado?',
                scope: this,
                fn: function(bnt) {
                    if(bnt == 'no') return;

                    mask.show();
                    Ext.Ajax.request({
                        url: toolkit.util.Normalize.controller_action('PHAMeterage', 'unpay'),
                        scope: this,
                        params: {
                            pk: this.getSelectionModel().getSelected().get('pk')
                        },
                        success: function(response, opts) {
                            var obj = Ext.decode(response.responseText);

                            if (obj.success)
                                this.getStore().reload();

                            Ext.Msg.show({
                                title: this.title,
                                icon: Ext.Msg.INFO,
                                buttons: Ext.Msg.OK,
                                msg: obj.message
                            });
                        },
                        failure: function(response, opts) {
                            var obj = Ext.decode(response.responseText);

                            Ext.Msg.show({
                                title: this.title,
                                icon: Ext.Msg.ERROR,
                                buttons: Ext.Msg.OK,
                                msg: obj.message
                            });
                        },
                        callback: function() {
                            mask.hide();
                            mask = null;
                        }
                    });
                }
            });
        }
        else
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione os pagamentos que deseja desfazer.'
            });
    },

    _payTheMan: function() {
        var sels = this.getSelectionModel().getSelections();

        if (sels.length > 0) {
            this._payWindow = Ext._create('planning.hiring.meterage.PaymentWindow', {
                params: {
                    pagamento: this.pagamento,
                    meterageGrid: this
                },
                callback: {
                    success: {
                        scope: this,
                        fn: function(args) {
                            this.getStore().reload();
                        }
                    }
                },
                action: 'create',
            });
            this._payWindow.show();
        }
        else {
            Ext.Msg.show({
                title: this.title,
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um registro para pagar'
            });
        }

    },

    getReportAction: function() {
        if(!this._reportAction)
            this._reportAction = Ext._create('Ext.Button', {
                text: 'Relatórios',
                iconCls: 'icon-agree icon-agree-application-pdf',
                scope: this,
                menu: [
                    {
                        text: 'Despachos',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: this._dispatch
                    },
                    {
                        text: 'Extrato do Contrato',
                        scope: this,
                        iconCls: 'icon-agree icon-agree-application-pdf',
                        handler: this._payment
                    },
                ]
            });

        return this._reportAction;
    },

    _payment: function() {
        var wnd = Ext._create('planning.hiring.meterage.ReportPayment');
        wnd.show();
    },

    _dispatch: function() {
        var sels = this.getSelectionModel().getSelections();
        if (sels.length > 0) {
            Ext.Ajax.request({
                url: toolkit.util.Normalize.controller_action('PHAMeterage', 'get_logged_employee_id'),
                scope: this,
                params: {
                    contrato: this.contrato
                },
                success: function(response, opts) {
                    var obj = Ext.decode(response.responseText);
                    this.logged_employee_id = obj.logged_employee_id;
                    engine.mq.Report.request({
                        report: '/to/mpe/planejamento/Solicitacao_Pagamento_de_Contrato',
                        el: this.getEl(),
                        waitMessage: 'Gerando relatório...',
                        params: {
                            outfile: 'despacho_pagamento_' + new Date().format("d/m/Y"),
                            report_name: 'Despacho de Pagamento',
                            contrato: this.contrato,
                            employee_id: this.logged_employee_id,
                            medicao: this.getSelectionModel().getSelections().map(
                                function(record) {
                                    return record.get('pk');
                                }
                            ).join()
                        }
                    });
                    
                },
                failure: function(response, opts) {
                    var obj = Ext.decode(response.responseText);

                    Ext.Msg.show({
                        title: this.title,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: obj.message
                    });
                },
            });
        } else {
            Ext.Msg.show({
                title: 'Despacho',
                icon: Ext.Msg.WARNING,
                buttons: Ext.Msg.OK,
                msg: 'Selecione um pagamento para gerar o despacho'
            });
        }
    },

    constructor: function(cfg) {
        cfg = (cfg ? cfg : {});

        Ext.applyIf(cfg, {
            columnAction: false,
        });

        planning.hiring.meterage.Grid.superclass.constructor.call(this, cfg);
    }
});

core.RestfulGrid.register(
    'planning.hiring.meterage.Restful',
    'planning.hiring.meterage.Grid'
);
